def findTargetSumWays(nums, target):
    total = sum(nums)
    if abs(target) > total or (total + target) % 2 != 0:
        return 0
    s = (total + target) // 2
    dp = defaultdict(int)
    dp[0] = 1
    for x in nums:
        next_dp = defaultdict(int)
        for current_sum, count in dp.items():
            next_dp[current_sum] += count
            if current_sum + x <= s:
                next_dp[current_sum + x] += count
        dp = next_dp
    return dp[s]
